import { useState } from "react";
import "./App.css";


 const HARD_CODED_VALUES = {
    heartRateRange: "Comfort: 60-100, Monitor: 100-120, Stop exercise: >120",
    exerciseList: [
      "Bike (New Step)",
      "Cable row (Techno)",
      "Chest press (Hammer)",
      "Leg press (Techno)",
      "Step up (Stairs)",
      "Hip flexion (Parallel bars)",
      "Shoulder raise (Dumbells)"
    ],
    repsTime: [
      "15 min",
      "10 reps (bilateral)",
      "10 reps (bilateral)",
      "10 reps (unilateral)",
      "10 reps (unilateral)",
      "15 reps (unilateral)",
      "15 reps (unilateral)",
      "15 reps (unilateral)"
    ],
    weightIntensity: [
      "L1 - 5 min",
      "L2 - 10 min",
      "40 lbs",
      "30 lbs",
      "80 lbs",
      "NA",
      "NA",
      "5 lbs"
    ]
  };
function App() {
  const [key, setKey] = useState("");
  const [user, setUser] = useState(null);
  const [error, setError] = useState("");

  const login = async () => {
    const res = await fetch("http://localhost:5000/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ key })
    });
    const data = await res.json();
    if (!res.ok) {
      setError(data.message);
      return;
    }
    setUser(data.user);
    setError("");
  };

if (!user) {
  return (
    <div className="login-container">
      <h1>Key Login</h1>
      <input
        value={key}
        onChange={(e) => setKey(e.target.value)}
        placeholder="Enter your key"
      />
      <button className="login-button" onClick={login}>
        Login
      </button>
      {error && <p className="error-message">{error}</p>}
    </div>
  );
}


if (user.role === "patient") {
  // Sort heart rates by timestamp ascending
  const sortedHeartRates = [...user.heart_rates].sort(
    (a, b) => new Date(a.timestamp) - new Date(b.timestamp)
  );

  return (
    <div className="patient-container">
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>
        Welcome {user.name}
      </h1>
      <div className="patient-info">
        <span>Age: {user.age}</span>
        <span>Sex: {user.sex}</span>
      </div>
      <h3 style={{ textAlign: "center", marginBottom: "10px" }}>
        Heart Rate Records
      </h3>
      <table className="patient-table">
        <thead>
          <tr>
            <th>#</th>
            <th>Timestamp</th>
            <th>Heart Rate</th>
          </tr>
        </thead>
        <tbody>
          {sortedHeartRates.map((r, i) => (
            <tr key={i}>
              <td>{i + 1}</td>
              <td>{r.timestamp}</td>
              <td>{r.heart_rate}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}


  if (user.role === "doctor") {
  return (
    <div className="doctor-container">
      <h1 style={{ textAlign: "center", marginBottom: "20px" }}>
        Doctor Dashboard: {user.name}
      </h1>
      <table className="doctor-table">
        <thead>
          <tr>
            <th>User Info</th>
            <th>Heart Rate / Exercise</th>
            <th>Heart Rate Range / Reps</th>
            <th>Weight/Intensity</th>
          </tr>
        </thead>
        <tbody>
          {user.patients.map((p) => (
            <>
              <tr key={p.key + "-1"}>
                <td rowSpan="2">
                  <strong>{p.name}</strong>
                  <br />
                  Age: {p.age}, Gender: {p.sex}
                </td>
                <td>{p.heart_rate || "-"}</td>
                <td>{HARD_CODED_VALUES.heartRateRange}</td>
                <td></td>
              </tr>
              <tr key={p.key + "-2"}>
                <td>
                  {HARD_CODED_VALUES.exerciseList.map((ex, i) => (
                    <span key={i}>
                      {ex}
                      <br />
                    </span>
                  ))}
                </td>
                <td>
                  {HARD_CODED_VALUES.repsTime.map((r, i) => (
                    <span key={i}>
                      {r}
                      <br />
                    </span>
                  ))}
                </td>
                <td>
                  {HARD_CODED_VALUES.weightIntensity.map((w, i) => (
                    <span key={i}>
                      {w}
                      <br />
                    </span>
                  ))}
                </td>
              </tr>
            </>
          ))}
        </tbody>
      </table>
    </div>
  );
}


  return null;
}

export default App;
